#include "IRremote.h"
IRrecv irrecv(A1);
decode_reults results;
#define G 12
#define R 10
#define B 8
#define B1 16718055
#define B2 16718055
#define B3 16718055
#define B4 16718055
void setup() {
   Serial.begin(9600);
   irrecv.enableIRIn();
   pinMode(G, OUTPUT);
   pinMode(R, OUTPUT);
   pinMode(B, OUTPUT);
}

void loop() {
   if (irrecv.decode(&results)) {
      Serial.println(results.value);

      if (results.value == B1) { digitalWrite(G, HIGH); }
      if (results.value == B2) { digitalWrite(R, HIGH); }
      if (results.value == B3) { digitalWrite(B, HIGH); }

      if (results.value == B4) {
         digitalWrite(G, LOW); digitalWrite(R, LOW); digitalWrite(B, LOW);
        }

      irrecv.resume();
   }
}
